{
  "errors": [
    {
      "error_type": "时间信息非法",
      "spans": [
        {
          "text": "2003年公司推出沙发推杆产品；208年推出办公台推杆产品；"
        }
      ],
      "reason": "公司1992年成立，208年远早于成立时间，年份不合法，应为2018年。"
    },
    {
      "error_type": "数值缺失",
      "spans": [
        {
          "text": "2024年全球可升降办公桌所应用线性驱动产品的市场规模大约为亿元，2021-2024年CAGR约为18.2%。"
        }
      ],
      "reason": "“大约为亿元”中缺少具体市场规模数值，无法核验。"
    },
    {
      "error_type": "计算错误",
      "spans": [
        {
          "text": "Marketsand Markets报告显示，全球智能家居市场规模预计将从2022年的845亿美元增长到2026年的1389亿美元，2022-2026年CAGR为17.4%。"
        }
      ],
      "reason": "按845到1389的4年增长计算，CAGR约13.2%，与文中17.4%不符。"
    },
    {
      "error_type": "计算错误",
      "spans": [
        {
          "text": "GlobaI InfoResearch数据显示，2022年全球电动尾门系统市场规模达到了16.3亿美元，预计2029年将达到28.4亿美元，年复合增长率为7.8%。"
        }
      ],
      "reason": "按16.3到28.4的7年增长计算，年复合增长率约8.25%，与文中7.8%不符。"
    },
    {
      "error_type": "数值不一致错误",
      "spans": [
        {
          "text": "2022年，全球线性驱动市场前六名分别为力纳克、德沃康、迪摩讯、捷昌驱动、凯迪股份以及乐歌股份，市占率分别为31%/31%/13%/12%/8%/1%/5%。"
        }
      ],
      "reason": "前六名仅对应6家公司，却列出7个市占率，且合计101%，数量与数值不匹配。"
    },
    {
      "error_type": "语义逻辑矛盾",
      "spans": [
        {
          "text": "汽车电动尾门渗透率持续下降，成为公司收入增长新动能"
        }
      ],
      "reason": "渗透率下降通常不利于收入增长，与“成为公司收入增长新动能”矛盾。"
    },
    {
      "error_type": "术语误用",
      "spans": [
        {
          "text": "并且线性驱动器产品和机器人线性关节工作原理相同，均是通过丝杠将电机的旋转运动转化为直线运用。"
        }
      ],
      "reason": "“直线运用”不是描述运动形式的专业术语，应为“直线运动”。"
    }
  ]
}
